package cn.huankan.collector;
import java.util.*;import java.time.*;import java.net.*;import java.net.http.*;import cn.huankan.evidence.EvidenceService;import com.fasterxml.jackson.databind.*;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
@Service public class AlfredService {
 private final JdbcTemplate db;private final FredConfiguration config;private final CollectorGuard guard;private final TransactionTemplate tx;private final ObjectMapper json=new ObjectMapper();
 public AlfredService(JdbcTemplate db,FredConfiguration config,CollectorGuard guard,PlatformTransactionManager manager){this.db=db;this.config=config;this.guard=guard;tx=new TransactionTemplate(manager);}
 public record Request(String seriesId,LocalDate asOf,LocalDate observationStart,LocalDate observationEnd){}
 public Object status(){return Map.of("state",config.ready()?"配置具备，ALFRED仍须逐序列许可与真实请求验证":"FRED/ALFRED凭证与白名单未就绪，未执行真实采集","snapshot_count",db.queryForObject("SELECT count(*) FROM alfred_snapshot",Long.class),"official_documentation","https://fred.stlouisfed.org/docs/api/fred/series_observations.html","actual_connected",db.queryForObject("SELECT EXISTS(SELECT 1 FROM alfred_snapshot)",Boolean.class));}
 public Object collect(Request q){if(!config.ready())throw new IllegalStateException(config.state());if(q.seriesId()==null||!config.whitelist().contains(q.seriesId())||q.asOf()==null||q.asOf().isAfter(LocalDate.now(ZoneOffset.UTC))||q.observationStart()==null||q.observationEnd()==null||q.observationEnd().isBefore(q.observationStart())||q.observationEnd().isAfter(q.asOf()))throw new IllegalArgumentException("ALFRED序列或历史日期范围无效");if(!Boolean.TRUE.equals(db.queryForObject("SELECT status='APPROVED' AND access_allowed AND storage_allowed AND display_allowed AND (valid_until IS NULL OR valid_until>now()) FROM source_license WHERE source_id='FRED'",Boolean.class)))throw new IllegalStateException("FRED/ALFRED序列许可尚未核验");
  try(var lease=guard.acquire("FRED")){if(lease==null)throw new IllegalStateException("FRED任务正在执行");UUID job=UUID.randomUUID();db.update("INSERT INTO ingestion_job(id,source_id,status) VALUES(?,'FRED','RUNNING')",job);String visible="https://api.stlouisfed.org/fred/series/observations?series_id="+q.seriesId()+"&realtime_start="+q.asOf()+"&realtime_end="+q.asOf()+"&observation_start="+q.observationStart()+"&observation_end="+q.observationEnd()+"&limit=1000&file_type=json";Integer status=null;long started=System.nanoTime();
   try{guard.request("api.stlouisfed.org");var r=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(15)).followRedirects(HttpClient.Redirect.NEVER).build().send(HttpRequest.newBuilder(URI.create(visible+"&api_key="+config.key())).timeout(Duration.ofSeconds(30)).GET().build(),HttpResponse.BodyHandlers.ofInputStream());status=r.statusCode();byte[] bytes;try(var in=r.body()){bytes=in.readNBytes(4194305);}db.update("INSERT INTO http_request_observation(source_id,endpoint,attempted_at,completed_at,status,duration_ms,response_bytes) VALUES('FRED',?,clock_timestamp()-?*interval '1 millisecond',clock_timestamp(),?,?,?)",visible,(System.nanoTime()-started)/1000000,status,(System.nanoTime()-started)/1000000,bytes.length);if(status==429)guard.cooldown("api.stlouisfed.org",Instant.now().plusSeconds(300).toEpochMilli());if(status!=200)throw new IllegalStateException("HTTP_"+status);if(bytes.length>4194304)throw new IllegalArgumentException("ALFRED响应超过4MiB");JsonNode root=json.readTree(bytes),obs=root.path("observations");if(!obs.isArray()||root.path("count").asInt()>1000||obs.size()>1000)throw new IllegalArgumentException("ALFRED历史超过有界预算，未保存不完整结果");
    UUID snapshot=tx.execute(s->{UUID response=UUID.randomUUID(),id=UUID.randomUUID();db.update("INSERT INTO official_response(id,source_id,job_id,url,response_status,raw_content,sha256) VALUES(?,'FRED',?,?,200,?,?)",response,job,visible,bytes,EvidenceService.hash(bytes));db.update("INSERT INTO alfred_snapshot(id,series_id,as_of,observation_start,observation_end,response_id) VALUES(?,?,?,?,?,?)",id,q.seriesId(),java.sql.Date.valueOf(q.asOf()),java.sql.Date.valueOf(q.observationStart()),java.sql.Date.valueOf(q.observationEnd()),response);for(var o:obs){LocalDate date=LocalDate.parse(o.path("date").asText()),start=LocalDate.parse(o.path("realtime_start").asText()),end=LocalDate.parse(o.path("realtime_end").asText());if(date.isBefore(q.observationStart())||date.isAfter(q.observationEnd())||start.isAfter(q.asOf())||end.isBefore(q.asOf()))throw new IllegalArgumentException("ALFRED响应包含范围之外或未来版本");String value=o.path("value").asText();db.update("INSERT INTO alfred_observation VALUES(?,?,?,?,?)",id,java.sql.Date.valueOf(date),value.equals(".")?null:new java.math.BigDecimal(value),java.sql.Date.valueOf(start),java.sql.Date.valueOf(end));}db.update("UPDATE ingestion_job SET status='SUCCESS',http_status=200,finished_at=now(),fetched_count=? WHERE id=?",obs.size(),job);return id;});return Map.of("snapshot_id",snapshot,"observations",obs.size(),"message","实际官方历史响应已保存；没有补造逐秒发布时间或交易行情");
   }catch(Exception e){db.update("UPDATE ingestion_job SET status='FAILED',finished_at=now(),http_status=?,error_code=? WHERE id=?",status,CollectorGuard.failure(e),job);throw new IllegalStateException("ALFRED请求未通过，已有数据保持不变");}
  }catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("ALFRED采集锁失败");}
 }
 public record Query(String seriesId,Instant asOf,int page){}
 public Object unified(Query q){if(q.page()<0||q.page()>100000||q.seriesId()==null||q.seriesId().length()>100||q.asOf()!=null&&q.asOf().isAfter(Instant.now()))throw new IllegalArgumentException("统一宏观查询参数无效");Instant asOf=q.asOf()==null?Instant.now():q.asOf();return Map.of("items",db.queryForList("SELECT * FROM unified_macro_observation WHERE (?='' OR series_id=?) AND acquired_at<=? AND (source_realtime_start IS NULL OR source_realtime_start<=?::date) ORDER BY acquired_at DESC,series_id,observation_date DESC LIMIT 100 OFFSET ?",q.seriesId(),q.seriesId(),java.sql.Timestamp.from(asOf),java.sql.Date.valueOf(asOf.atOffset(ZoneOffset.UTC).toLocalDate()),q.page()*100),"as_of",asOf,"semantics","证据取得时点限制；官方历史版本时点缺失时不推断市场何时已经知晓","source_published_at","未在统一模型中假定发布时间");}
}
